#include <iostream>
#include <vector>
#include <cstdint>

int main() {
    int32_t left, right;
    std::cin >> left >> right;

    if (right < 2 || left > right) {
        std::cout << 0;
        return 0;
    }

    std::vector<bool> numbers(static_cast<size_t>(right) + 1, false);

    for (int64_t i = 1; i * i <= right; ++i) {
        for (int64_t j = i; i * i + j * j <= right; ++j) {
            int64_t num = i * i + j * j;
            if (num >= left)
                numbers[static_cast<size_t>(num)] = true;
        }
    }

    std::vector<bool> prime(static_cast<size_t>(right) + 1, true);
    prime[0] = false;
    prime[1] = false;

    for (int64_t i = 2; i * i <= right; ++i) {
        if (!prime[static_cast<size_t>(i)])
            continue;

        for (int64_t j = i * i; j <= right; j += i)
            prime[static_cast<size_t>(j)] = false;
    }

    int32_t answer = 0;
    for (int32_t i = std::max<int32_t>(left, 2); i <= right; ++i) {
        if (numbers[static_cast<size_t>(i)] &&
            prime[static_cast<size_t>(i)]) {
            ++answer;
        }
    }

    std::cout << answer;
    return 0;
}

